function initPortfolioFilter() {
  if (!window.gsap || !window.Flip) return;
  gsap.registerPlugin(Flip);

  var grid = document.querySelector('.portfolio-grid-wrapper');
  var items = gsap.utils.toArray('.single-project');
  var buttons = gsap.utils.toArray('.filter-category');
  if (!grid || !items.length || !buttons.length) return;

  var norm = function (s) { return (s || '').trim().toLowerCase(); };
  var animating = false;

  function catOf(item) {
    var s = item.querySelector('[data-category]') || item;
    return norm(s.getAttribute('data-category'));
  }

  function refreshScroll() {
    if (window.ScrollTrigger) window.ScrollTrigger.refresh();
  }

  function applyFilter(filter) {
    if (animating) return;

    var show = [],
      hide = [];
    items.forEach(function (it) {
      ((filter === 'all' || catOf(it) === filter) ? show : hide).push(it);
    });
    var leaving = hide.filter(function (it) { return !it.classList.contains('is-hidden'); });
    var entering = show.filter(function (it) { return it.classList.contains('is-hidden'); });

    animating = true;

    // Faz 2+3: layout'u Flip ile anime et, girenleri fade-in yap
    function relayout() {
      var state = Flip.getState(items); // çıkanlar artık akışta değil
      hide.forEach(function (it) { it.classList.add('is-hidden'); });
      show.forEach(function (it) { it.classList.remove('is-hidden'); });
      gsap.set(entering, { opacity: 0 }); // popping yerine fade için

      Flip.from(state, {
        duration: 0.5,
        ease: 'power2.inOut',
        scale: true, // transform tabanlı -> boyut sıçraması yok
        onComplete: function () {
          refreshScroll();
          animating = false;
        }
      });
      gsap.to(entering, { opacity: 1, duration: 0.4, delay: 0.15 });
    }

    // Faz 1: çıkanları önce fade-out, bittiğinde relayout
    if (leaving.length) {
      gsap.to(leaving, { opacity: 0, duration: 0.25, onComplete: relayout });
    } else {
      relayout();
    }
  }

  buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      buttons.forEach(function (b) { b.classList.remove('category-selected'); });
      btn.classList.add('category-selected');
      // tekrar görünür olan kartların opacity'sini sıfırla (önceki fade-out kalıntısı)
      items.forEach(function (it) {
        if (it.classList.contains('is-hidden')) gsap.set(
          it, { opacity: 1 });
      });
      applyFilter(norm(btn.getAttribute('data-filter')));
    });
  });
}

function DNAScene() {

  if (!window.gsap || !window.ScrollTrigger || mobileQuery.matches) { return; }
  gsap.registerPlugin(ScrollTrigger);

  var section = document.querySelector('#about-dna');
  var wrap = document.querySelector('.dna-infos-wrap');
  var boxes = wrap ? [].slice.call(wrap.querySelectorAll('.dna-info-box')) : [];
  var headline = document.querySelector('#dna-headline');
  if (!section || !boxes.length) return;

  /* ---- Sol-alt dinamik metin: her adım için bir satır (BURAYI DÜZENLE) ---- */
  var PHRASES = [
    'NOUS VOUS OFFRONS <br>UNE CLARTÉ TECHNIQUE, <br>UNE VISION DE MARQUE',
    'NOUS TRANSFORMONS <br>LA COMPLEXITÉ <br>EN STRATÉGIE',
    'NOUS FAÇONNONS <br>LES IDÉES <br>EN EXPÉRIENCE',
    'NOUS RESTONS <br>À VOS CÔTÉS, <br>TOUJOURS'
  ];

  var steps = boxes.length;

  /* kapsayıcı yüksekliği = en uzun kutu (absolute yığında çökmesin) */
  function sizeWrap() {
    var h = 0;
    boxes.forEach(function (b) { h = Math.max(h, b.offsetHeight); });
    if (h) wrap.style.minHeight = h + 'px';
  }
  /* başlık yüksekliğini kilitle (metin değişince zıplama olmasın) */
  function sizeHeadline() {
    if (headline) {
      headline.style.minHeight = '';
      headline.style.minHeight = headline.offsetHeight + 'px';
    }
  }
  sizeWrap();
  sizeHeadline();

  var current = -1,
    first = true;

  function setStep(i) {
    if (i === current) return;
    current = i;
    boxes.forEach(function (b, idx) {
      b.classList.toggle('is-active', idx === i);
      b.classList.toggle('is-past', idx < i);
    });
    if (headline && PHRASES[i] != null) {
      headline.innerHTML = PHRASES[i];
      if (!first) {
        headline.classList.remove('is-anim');
        void headline.offsetWidth; // animasyonu yeniden tetikle
        headline.classList.add('is-anim');
      }
    }
    first = false;
  }

  ScrollTrigger.create({
    trigger: section,
    start: 'top top',
    end: '+=' + (steps * 100) + '%', // adım başına ~1 ekran scroll
    pin: true,
    pinSpacing: true,
    scrub: true,
    // anticipatePin: 1,
    invalidateOnRefresh: true,
    onRefresh: function () {
      sizeWrap();
      sizeHeadline();
    },
    onUpdate: function (self) {
      var i = Math.min(steps - 1, Math.floor(self.progress * steps));
      setStep(i);
    }
  });

  setStep(0);
}

function aboutClientsScene() {
  if (!window.gsap || !window.ScrollTrigger || mobileQuery.matches) { return; }

  function splitLines(el) {
    if (!el) return [];
    var words = (el.textContent || '').trim().split(/\s+/);
    if (!words[0]) return [];
    el.textContent = '';
    // kelimeleri inline-block olarak ekle (offsetTop güvenilir olsun)
    var frag = document.createDocumentFragment();
    var wordSpans = words.map(function (w) {
      var s = document.createElement('span');
      s.textContent = w;
      s.style.display = 'inline-block';
      frag.appendChild(s);
      frag.appendChild(document.createTextNode(' '));
      return s;
    });
    el.appendChild(frag);
    // görsel satırlara göre grupla
    var lines = [],
      cur = null,
      top = null;
    wordSpans.forEach(function (s) {
      var t = s.offsetTop;
      if (top === null || Math.abs(t - top) > 1) {
        cur = [];
        lines.push(cur);
        top = t;
      }
      cur.push(s);
    });
    // block satır sarmalayıcılarıyla yeniden kur (CSS'e bağımlı değil)
    el.textContent = '';
    return lines.map(function (group) {
      var line = document.createElement('span');
      line.className = 'cl-line';
      line.style.display = 'block';
      group.forEach(function (s, i) {
        line.appendChild(s);
        if (i < group.length - 1) line.appendChild(document.createTextNode(' '));
      });
      el.appendChild(line);
      return line;
    });
  }

  var section = document.querySelector('#about-clients');
  var cred = section && section.querySelector('.credentials');
  var boxWrap = section && section.querySelector('.client-box-wrapper');
  if (!section || !cred || !boxWrap) return;

  section.classList.add('cl-init');

  var subtitle = cred.firstElementChild; // "02 // credentials"
  var heading = cred.querySelector('.heading-4');
  var para = cred.querySelector('.credentials-text');
  var boxes = [].slice.call(boxWrap.querySelectorAll('.client-box'));

  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  var headLines = splitLines(heading);
  var paraLines = splitLines(para);
  var credItems = [];
  if (subtitle) credItems.push(subtitle);
  credItems = credItems.concat(headLines, paraLines);

  // ---- başlangıç: hiçbir şey görünmez, sağda bekler ----
  gsap.set(credItems, { opacity: 0, x: 60 });
  gsap.set(boxes, { opacity: 0, y: 60 });
  gsap.set(cred.querySelectorAll('.credentials-title'), { opacity: 1 }); // wrapper'ı açık tut

  var tl = gsap.timeline({
    scrollTrigger: {
      trigger: section,
      start: 'top top',
      end: '+=320%',
      pin: true,
      pinSpacing: true,
      scrub: true,
      anticipatePin: 1,
      invalidateOnRefresh: true
    }
  });

  // 1) Credentials: sağdan sola fade-in (satırlar staggered)
  tl.to(credItems, { opacity: 1, x: 0, duration: 1, stagger: 0.12, ease: 'power3.out' }, 0);
  // 2) Credentials: sola fade-out (aynı yönde devam)
  tl.to(credItems, { opacity: 0, x: -60, duration: 0.8, stagger: 0.08, ease: 'power3.in' },
    '+=0.5');
  // 3) Client boxes: fade-up in
  tl.to(boxes, { opacity: 1, y: 0, duration: 1, stagger: 0.12, ease: 'power3.out' }, '+=0.15');
  // 4) Client boxes: fade-up out
  tl.to(boxes, { opacity: 0, y: -60, duration: 0.8, stagger: 0.1, ease: 'power3.in' }, '+=0.5');

  ScrollTrigger.refresh();

  return tl;
}

function aboutTeamScene() {
  if (!window.gsap || !window.ScrollTrigger || mobileQuery.matches) { return; }

  var hasMP = !!window.MotionPathPlugin;
  if (hasMP) gsap.registerPlugin(MotionPathPlugin);

  function splitLines(el) {
    if (!el) return [];
    var words = (el.textContent || '').trim().split(/\s+/);
    if (!words[0]) return [];
    el.textContent = '';
    var frag = document.createDocumentFragment();
    var wordSpans = words.map(function (w) {
      var s = document.createElement('span');
      s.textContent = w;
      s.style.display = 'inline-block';
      frag.appendChild(s);
      frag.appendChild(document.createTextNode(' '));
      return s;
    });
    el.appendChild(frag);
    var lines = [],
      cur = null,
      top = null;
    wordSpans.forEach(function (s) {
      var t = s.offsetTop;
      if (top === null || Math.abs(t - top) > 1) {
        cur = [];
        lines.push(cur);
        top = t;
      }
      cur.push(s);
    });
    el.textContent = '';
    return lines.map(function (group) {
      var line = document.createElement('span');
      line.className = 'tm-line';
      line.style.display = 'block';
      group.forEach(function (s, i) {
        line.appendChild(s);
        if (i < group.length - 1) line.appendChild(document.createTextNode(' '));
      });
      el.appendChild(line);
      return line;
    });
  }

  var section = document.querySelector('#about-team');
  if (!section) return;
  section.classList.add('tm-init');

  var subtitle = section.querySelector('.team-section-title');
  var heading = section.querySelector('#team-heading');
  var text = section.querySelector('#team-text');
  var members = [].slice.call(section.querySelectorAll('.team-member'));
  if (!members.length) return;

  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  // --- title + text: sağdan staggered fade-in, ÇIKIŞ YOK ---
  var headLines = splitLines(heading);
  var paraLines = splitLines(text);
  var credItems = [];
  if (subtitle) credItems.push(subtitle);
  credItems = credItems.concat(headLines, paraLines);

  gsap.set(credItems, { autoAlpha: 0, x: 60 });
  gsap.set([heading, text], { opacity: 1 });

  // --- üyeler: gerçekten ekranın altından gelsin ---
  var fromY = Math.round((window.innerHeight || 800) * 0.6); // ekran altı
  gsap.set(members, {
    autoAlpha: 0,
    x: 60,
    y: fromY,
    scale: 0.88,
    filter: 'blur(24px)',
    transformOrigin: '50% 50%'
  });

  var tl = gsap.timeline({
    scrollTrigger: {
      trigger: section,
      start: 'top top',
      end: '+=520%', // pin mesafesi (tunable)
      pin: true,
      pinSpacing: true,
      scrub: true,
      anticipatePin: 1,
      invalidateOnRefresh: true
    }
  });

  // 1) title + text giriş (kalıcı)
  tl.to(credItems, { autoAlpha: 1, x: 0, duration: 1, stagger: 0.12, ease: 'power3.out' }, 0);
  tl.addLabel('members', '+=0.4');

  var last = members.length - 1;
  members.forEach(function (m, i) {
    var inPos = (i === 0) ? 'members' : '-=0.55';

    if (hasMP) {
      // GİRİŞ — manuel path: alttan -> hafif yana süzül -> merkeze
      tl.to(m, {
        autoAlpha: 1,
        scale: 1,
        filter: 'blur(0px)',
        duration: 1.5,
        ease: 'expo.out',
        motionPath: {
          path: [
            { x: 60, y: fromY }, // ekran altı (başlangıç)
            { x: -34, y: Math.round(fromY * 0.42) }, // yolda hafif sola süzülme
            { x: 0, y: 0 } // merkez (rest)
          ],
          curviness: 1.5,
          autoRotate: false
        }
      }, inPos);
    } else {
      // Fallback (MotionPath yoksa) — yine alttan, y ile
      tl.to(m, {
        autoAlpha: 1,
        x: 0,
        y: 0,
        scale: 1,
        filter: 'blur(0px)',
        duration: 1.5,
        ease: 'expo.out'
      }, inPos);
    }

    if (i < last) {
      // SÜZÜLME — kısa süre merkezde süzülsün
      tl.to(m, { y: -24, scale: 1.03, duration: 0.8, ease: 'sine.inOut' });
      // ÇIKIŞ — yukarı + blur
      tl.to(m, {
        autoAlpha: 0,
        y: -180,
        filter: 'blur(12px)',
        duration: 1.0,
        ease: 'power2.in'
      });
    }
    // son üye: sadece giriş, merkezde net kalır
  });

  ScrollTrigger.refresh();
  return tl;
}

function clientsCarousel() {

  if (!document.querySelectorAll('.clients-carousel').length) return;

  let clientsCarousel = document.querySelectorAll('.clients-carousel');

  clientsCarousel.forEach(($this) => {
    const original = $this.innerHTML
    const originalWidth = $this.offsetWidth

    for (let e = 0; e <= window.innerWidth / originalWidth; e++) {
      $this.innerHTML += original
    }

    $this.style.setProperty('--scroll-width', originalWidth + 'px')

    const speed = 0.025
    const duration = originalWidth * speed
    $this.style.setProperty('--scroll-duration', duration + 's')
  })

}

function initLoaderThreeSteps() {

  if (!document.querySelector('.loading-container')) return;

  var tl = gsap.timeline({
    defaults: {
      ease: "Expo.easeInOut",
      duration: 1,
      onStart: () => {
        setTimeout(function () {
          document.querySelector('.loading-screen').classList.add(
            'loader-active')
        }, 100);

      }
    }
  });

  /* Loading numbers */
  var randomNumbers1 = gsap.utils.random([2, 3, 4]);
  var randomNumbers2 = gsap.utils.random([5, 6]);
  var randomNumbers3 = gsap.utils.random([1, 5]);
  var randomNumbers4 = gsap.utils.random([7, 8, 9]);

  /* Sayfa yüklendi mi? */
  var pageLoaded = document.readyState === "complete";
  window.addEventListener("load", function () {
    pageLoaded = true;
    // Timeline pause noktasında bekliyorsa devam ettir
    if (tl.paused()) {
      tl.play();
    }
  });

  /* Loading Timeline */
  tl.set(".loading-screen", {
    display: "block",
  });

  tl.set(".loading__progress-inner", {
    scaleY: 0,
    transformOrigin: "bottom"
  });

  tl.set(".loading__number-group.is--first .loading__number-wrap, .loading__percentage", {
    yPercent: 100
  });

  tl.set(
    ".loading__number-group.is--second .loading__number-wrap, .loading__number-group.is--third .loading__number-wrap", {
      yPercent: 10
    });

  /* ---- STEP 1 ---- */
  tl.to(".loading__progress-inner", {
    scaleY: (randomNumbers1 + "" + randomNumbers3) / 100,
  });

  tl.to(".loading__percentage", {
    yPercent: 0
  }, "<");

  tl.to(".loading__number-group.is--second .loading__number-wrap", {
    yPercent: (randomNumbers1 - 1) * -10,
  }, "<");

  tl.to(".loading__number-group.is--third .loading__number-wrap", {
    yPercent: (randomNumbers3 - 1) * -10,
  }, "<");

  /* ---- STEP 2 ---- */
  tl.to(".loading__progress-inner", {
    scaleY: (randomNumbers2 + "" + randomNumbers4) / 100,
  });

  tl.to(".loading__number-group.is--second .loading__number-wrap", {
    yPercent: (randomNumbers2 - 1) * -10,
  }, "<");

  tl.to(".loading__number-group.is--third .loading__number-wrap", {
    yPercent: (randomNumbers4 - 1) * -10,
  }, "<");

  /* ---- SAYFA YÜKLENME KONTROLÜ (2. STEP SONRASI) ----
     Sayfa yüklendiyse beklemeden devam eder.
     Yüklenmediyse burada durur, 'load' olayı gelince devam eder. */
  tl.addPause(null, function () {
    if (pageLoaded) {
      tl.play();
    }
    // pageLoaded false ise hiçbir şey yapma → yukarıdaki load listener devam ettirir
  });

  /* ---- STEP 3 (100%) ---- */
  tl.to(".loading__progress-inner", {
    scaleY: 1,
  });

  tl.to(".loading__number-group.is--second .loading__number-wrap", {
    yPercent: -90,
  }, "<");

  tl.to(".loading__number-group.is--third .loading__number-wrap", {
    yPercent: -90,
  }, "<");

  tl.to(".loading__number-group.is--first .loading__number-wrap", {
    yPercent: 0,
  }, "<");

  /* ---- ÇIKIŞ ANIMASYONU ----
     Line yukarı kayar, numaralar yukarı çıkar,
     en son tüm loading ekranı yukarı süzülerek kapanır. */

  // Line yukarı çıkış
  tl.to(".loading__progress-inner", {
    yPercent: -110,
    duration: 1,
  }, "+=0.3");

  // Tüm numaralar yukarı çıkış
  tl.to(".loading__number-group .loading__number-wrap, .loading__percentage", {
    yPercent: -120,
    duration: 1,
  }, "<");

  // Tüm loading ekranı yukarı süzülerek kapanış
  tl.to(".loading-screen", {
    yPercent: -100,
    duration: 1.2,
    onStart: () => {
      initAnimations();
    }
  }, "-=0.6");

  tl.set(".loading-screen", {
    display: "none",
  });
}

let peSpline = null;

const fadeOut = (el, d = 0.4) => gsap.to(el, { opacity: 0, duration: d });
const fadeIn = (el, d = 0.4) => gsap.to(el, { opacity: 1, duration: d });

/* ----- BURADAN AYARLA: süre / easing / spin / stagger -----
   spinY: kaç tam tur (işaretli). reset ileri (+1), form ters (-1).
   spinTarget: spin uygulanacak obje (varsayılan 'Main Cube'). Birden çok için dizi:
               ['Main Cube','Backdrop'] ; tümü için null.
   staggerTotal: TOPLAM stagger süresi (sn). Kaç obje olursa olsun toplam aynı kalır
   (ilk obje 0, son obje staggerTotal gecikmeyle başlar). 0 = stagger yok.            */
const RESET = {
  duration: 1.0,
  ease: 'osmo',
  spinY: 0,
  spinTarget: 'Main Cube',
  staggerTotal: 0.5
};
const FORM = {
  duration: 1.0,
  ease: 'osmo',
  spinY: 0,
  spinTarget: 'Main Cube',
  staggerTotal: 0.5
};
const FADE = 0.4;

/* İLK YÜKLEME: sahne mount'unu Barba dışına taşı, SplineLoader'ı bir kez kur. */
async function bootSplineOnce() {
  const firstContainer = document.querySelector('[data-barba="container"]');
  const mount = firstContainer && firstContainer.querySelector('.spline-mount');
  if (!mount) { console.warn('[barba-spline] ilk sayfada .spline-mount yok'); return; }

  const host = document.createElement('div');
  host.id = 'spline-persistent';
  document.body.appendChild(host);
  host.appendChild(mount); // DOM'dan koparmadan taşır -> WebGL korunur

  peSpline = new SplineLoader(mount.querySelector('.spline--canvas'), mount);
  window.peSpline = peSpline;
  await peSpline.ready;
}

/* Hedef container'daki spline-mount'tan JSON oku (render YOK), sonra o mount'u kaldır. */
async function readTargetData(container) {
  const mount = container.querySelector('.spline-mount');
  if (!mount) return { animations: [], objectPreferences: [] };
  const data = await peSpline.resolvePageData(mount);
  mount.remove(); // boş ikinci canvas görünmesin
  return data;
}

/* 3) Barba kurulumu */
async function initBarba() {
  await bootSplineOnce();

  barba.init({
    // Yeni gelen container'daki spline-mount'u DOM'a girer girmez gizle/temizle ki
    // boş ikinci bir canvas görünmesin (asıl sahne kalıcı host'ta).
    transitions: [{
      name: 'spline-fade',

      before(trigger) {

        if (trigger && trigger.trigger && trigger.trigger !== 'back' && parents(trigger
            .trigger, '[data-menu="open"]').length) {
          const toggle = parents(trigger.trigger, '[data-menu="open"]')[0].querySelector(
            '.site-nav-toggle');
          toggle.click();
        }

      },
      beforeEnter({ next }) { gsap.set(next.container, { opacity: 0 }); },

      // ESKİ sayfadan çıkış: içerik fadeout + sahne DEFAULT'a (ileri tur + state base'e)
      async leave({ current }) {
        peSpline.killPage();
        await Promise.all([
          fadeOut(current.container, FADE),
          peSpline.animateToDefaults(RESET), // spin + stagger + state animasyonu
        ]);
      },

      // YENİ sayfaya giriş: hedef başlangıç pozuna (ters tur) + animasyonları kur + fadein
      async enter({ next }) {
        window.scrollTo(0, 0);
        const { animations, objectPreferences } = await readTargetData(next.container);

        peSpline.setData(animations, objectPreferences);
        await peSpline.animateToInitial(FORM); // ters spin + stagger
        peSpline.initPage(); // scroll/normal anim + ScrollTrigger.refresh

        await fadeIn(next.container, FADE);
      },
    }],
  });
}

document.addEventListener('DOMContentLoaded', initBarba);

/* Initialize Number Loader in 3 Steps */

initLoaderThreeSteps();

function initOnceFunctions() {
  initLenis();
  siteHeader();

  // refreshInit → lenis.resize BİR KEZ bağlanır. (Önceden init() içindeydi; init() her Barba
  // geçişinde çalıştığı için her seferinde bir listener daha ekleniyordu = leak → her refresh'te
  // lenis.resize N kez çağrılıyor, sayfa gezindikçe kasma artıyordu.)
  ScrollTrigger.addEventListener('refreshInit', () => lenis.resize());
}

barba.hooks.beforeLeave(() => {
  // Spline'ın kendi trigger'ları peSpline.killPage()'de ayrıca temizleniyor;
  // burada site'ın TÜM trigger'larını öldür. enter'da init() yeniden kuruyor.
  // ScrollTrigger.getAll().forEach(st => st.kill());
});

barba.hooks.enter((data) => {
  init();

});

barba.hooks.after((data) => {
  initAnimations();
  ScrollTrigger.refresh(true);
  resetPage();
});

function init() {
  servicesCard();
  serviceLayers();

  initPortfolioFilter();

  contactMap();
  DNAScene();
  aboutClientsScene();

  aboutTeamScene();
  clientsCarousel();

  servicesSection();
  initImagesOnPathScroll();

  parallaxUtils();

  // Görseller yüklendikçe layout değişir → ScrollTrigger pozisyonlarını yenile. Ama HER görselde
  // ayrı refresh yerine TEK debounce'lu refresh (önceden her img load'da refresh çağrılıyordu;
  // mobilde bu refresh spam'i scroll sırasında native momentum'u tıkıyordu). {once} ile listener
  // kendini temizler.
  let _imgRefreshT;
  document.querySelectorAll('img').forEach((img) => {
    if (!img.complete) img.addEventListener('load', () => {
      clearTimeout(_imgRefreshT);
      _imgRefreshT = setTimeout(() => ScrollTrigger.refresh(), 200);
    }, { once: true });
  });

}

function initAnimations() {
  textUtils();
  animUtils();
  gsap.fromTo('.page-wrapper', {
    opacity: 0
  }, {
    opacity: 1
  })

}

document.addEventListener("DOMContentLoaded", () => {
  initOnceFunctions()
  init();

  if (!document.querySelector('.loading-container')) initAnimations();

});
